package app.polka.nativeapp

import android.content.Context
import android.graphics.*
import android.os.*
import android.view.*
import android.widget.*
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import org.json.*
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.*
import org.robolectric.annotation.*
import java.io.File
import java.util.concurrent.TimeUnit

@RunWith(RobolectricTestRunner::class)
@Config(sdk=[35],qualifiers="w360dp-h780dp-xxhdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class SwipeVisualTests {
 private lateinit var controller:org.robolectric.android.controller.ActivityController<MainActivity>
 private lateinit var a:MainActivity
 private lateinit var deck:RecommendationDeck
 private lateinit var host:LinearLayout
 private fun advance(ms:Long){repeat(((ms+15)/16).toInt()){Shadows.shadowOf(Looper.getMainLooper()).idleFor(16,TimeUnit.MILLISECONDS)}}
 private fun drain(){repeat(10){Thread.sleep(40);advance(80)}}
 private fun awaitVote(){repeat(250){if(!deck.busy)return;Thread.sleep(40);advance(32)};fail("vote did not finish within ten seconds")}
 private fun descendants(v:View):List<View> = listOf(v)+if(v is ViewGroup)(0 until v.childCount).flatMap{descendants(v.getChildAt(it))}else emptyList()
 private fun layout(){repeat(3){a.root.measure(View.MeasureSpec.makeMeasureSpec(a.d(360),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(a.d(780),View.MeasureSpec.EXACTLY));a.root.layout(0,0,a.d(360),a.d(780));advance(16)}}
 @Before fun open(){org.robolectric.shadows.ShadowChoreographer.setFrameDelay(java.time.Duration.ofMillis(16));org.robolectric.shadows.ShadowChoreographer.setPaused(true);val c=ApplicationProvider.getApplicationContext<Context>();c.deleteDatabase("polka.sqlite");val db=Room.databaseBuilder(c,LibraryDb::class.java,"polka.sqlite").allowMainThreadQueries().build();val lib=Library(db);lib.initialize();lib.savePrefs(lib.prefs().put("motion","reduced"));lib.save(JSONObject().put("id","fixture").put("title","Смотритель маяка").put("authors",JSONArray().put("Полка")).put("noFile",true).put("pos",0));lib.updateMarker();db.close();controller=Robolectric.buildActivity(MainActivity::class.java).setup();a=controller.get();drain();layout();MainActivity::class.java.getDeclaredField("tab").apply{isAccessible=true}.set(a,"foryou");a.render(false,false);drain();layout();a.page.removeAllViews();host=a.column();a.page.addView(host);val cat=JSONObject(a.assets.open("recs.json").bufferedReader().readText());deck=RecommendationDeck(a,host,cat,JSONObject().put("onboarded",true).put("coached",true));deck.start();layout();a.prefs.put("motion","normal")}
 @After fun close(){controller.pause().stop().destroy();org.robolectric.shadows.ShadowChoreographer.setPaused(false)}
 private fun card()=descendants(host).filterIsInstance<RecommendationCard>().last()
 private fun insets(bottom:Int)=WindowInsets.Builder().setInsets(WindowInsets.Type.statusBars(),Insets.of(0,a.d(24),0,0)).setInsets(WindowInsets.Type.navigationBars(),Insets.of(0,0,0,a.d(bottom))).build()
 private var down=0L
 private fun touch(action:Int,x:Float,y:Float){if(action==MotionEvent.ACTION_DOWN)down=SystemClock.uptimeMillis();val e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);a.root.dispatchTouchEvent(e);e.recycle();advance(16)}
 private fun origin(v:View):PointF{val p=IntArray(2);val r=IntArray(2);v.getLocationOnScreen(p);a.root.getLocationOnScreen(r);return PointF((p[0]-r[0]).toFloat(),(p[1]-r[1]).toFloat())}
 private fun drag(dx:Int,dy:Int):RecommendationCard{val v=card();val o=origin(v);val x=o.x+v.width/2;val y=o.y+v.height*.7f;touch(MotionEvent.ACTION_DOWN,x,y);touch(MotionEvent.ACTION_MOVE,x+a.d(dx),y+a.d(dy));advance(550);assertEquals("deck must own vertical gesture from DOWN",0,descendants(a.root).filterIsInstance<ScrollView>().first().scrollY);return v}
 private fun shot(name:String):Bitmap{val b=Bitmap.createBitmap(a.root.width,a.root.height,Bitmap.Config.ARGB_8888);a.root.draw(Canvas(b));val dir=File(System.getProperty("qaOutputDir"),"swipe-0.6.6").apply{mkdirs()};File(dir,"$name.png").outputStream().use{b.compress(Bitmap.CompressFormat.PNG,100,it)};return b}
 @Test fun menuSitsAtSafeBoundaryWithoutExtraFourteenDp(){for(bottom in listOf(0,24,28,48,280)){a.root.dispatchApplyWindowInsets(insets(bottom));layout();val nav=descendants(a.root).filterIsInstance<PolkaNavigation>().single();val add=descendants(a.root).first{it.contentDescription=="Добавить книги"};assertEquals(maxOf(a.d(4),a.d(bottom)),a.root.height-nav.bottom);assertEquals(nav.bottom,add.bottom);assertFalse(descendants(host).any{it.contentDescription=="Хочу прочитать"})};a.root.dispatchApplyWindowInsets(insets(24));layout();shot("native-navigation-low").recycle()}
 @Test fun heldRightCardDrawsAcrossInternalRightBoundary(){val v=drag(150,0);val o=origin(v);val b=shot("native-right");assertNotEquals("book pixels must reach last screen columns, outside padded host",a.bg,b.getPixel(a.root.width-a.d(2),(o.y+v.height*.5f).toInt().coerceIn(0,b.height-1)));b.recycle();assertFalse(host.clipChildren);assertFalse(host.clipToPadding)}
 @Test fun heldLeftCardDrawsAcrossInternalLeftBoundary(){val v=drag(-150,0);val o=origin(v);val b=shot("native-left");assertNotEquals("book pixels reach the physical left edge",a.bg,b.getPixel(a.d(2),(o.y+v.height*.5f).toInt().coerceIn(0,b.height-1)));b.recycle()}
 @Test fun heldUpCardCrossesHeaderAndStatusZoneWithoutScrollingPage(){drag(0,-230);val b=shot("native-up");assertNotEquals("upward book may pass behind status icons, not vanish at deck top",a.bg,b.getPixel(a.d(180),a.d(4)));b.recycle();assertEquals(-a.d(230).toFloat(),card().translationY,1.1f)}
 @Test fun cancelledVerticalGestureReturnsWithoutVoteOrScroll(){val v=drag(0,-130);val o=origin(v);touch(MotionEvent.ACTION_CANCEL,o.x+v.width/2,o.y+v.height*.7f);advance(650);assertEquals(0f,v.translationY,.5f);assertEquals(0f,v.translationX,.5f);assertNull(deck.state.optJSONObject("sw"));assertFalse(deck.busy);shot("native-cancelled").recycle()}
 @Test fun upwardReleaseOpensRatingWhileBookLeavesThroughScreenTop(){val v=drag(0,-130);val o=origin(v);touch(MotionEvent.ACTION_UP,o.x+v.width/2,o.y+v.height*.7f);assertTrue(deck.busy);val dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(dialog.isShowing);advance(550);assertTrue("flight is viewport sized",v.translationY < -a.root.height*.9f);shot("native-up-departed").recycle();descendants(dialog.window!!.decorView).filterIsInstance<TextView>().first{it.text.toString()=="Без оценки"}.performClick();awaitVote();layout();assertEquals("read",deck.state.getJSONObject("sw").getJSONObject(v.book.str("rec")).str("a"));assertEquals(0f,card().translationY,.5f)}
 @Test fun nextBookIsPromotedWithoutDestroyingItsView(){val cards=descendants(host).filterIsInstance<RecommendationCard>();val second=cards[cards.size-2];a.prefs.put("motion","reduced");deck.list=deck.list.drop(1);RecommendationDeck::class.java.getDeclaredMethod("fill",Boolean::class.javaPrimitiveType,RecommendationDeck.Undo::class.java).apply{isAccessible=true}.invoke(deck,false,null);layout();assertSame("recFill reuses a retained book already rising behind outgoing card",second,card());shot("native-next").recycle()}
 @Test fun tintForUpwardSwipeIsVerticalNotDiagonal(){val v=card();v.stamp("read",1f);val b=shot("native-up-tint");b.recycle();assertEquals(0f,v.translationX,0f)}
 @Test fun exactWebFlightKeyframesAndDurations(){val data=JSONArray(File(File(System.getProperty("recReferenceFixture")).parentFile,"swipes-web-reference.json").readText());for(i in 0 until data.length()){val row=data.getJSONObject(i);val f=row.optJSONObject("from")
 fun n(k:String):Float = f?.optDouble(k)?.toFloat() ?: 0f
 val flight=RecommendationFlight(360f,780f,row.getString("act"),n("dx"),n("dy"),n("vx"),n("vy"),if(f==null)1f else n("side"),f!=null);val keys=row.getJSONArray("keys");for(k in 0 until keys.length()){val key=keys.getJSONObject(k);val values=Regex("-?[0-9]+(?:\\.[0-9]+)?").findAll(key.getString("transform").replace("translate3d","translate")).map{it.value.toFloat()}.toList();val pose=flight.sample(if(k==0)0f else if(k==keys.length()-1)1f else .25f);assertEquals(values[0],pose.x,.01f);assertEquals(values[1],pose.y,.01f);assertEquals(values[3],pose.rotation,.01f)};assertEquals(row.getJSONObject("opts").getDouble("duration"),flight.duration.toDouble(),1.0)}}
 @Test fun searchOpensInsideToolbarAndExplicitlyRequestsKeyboard(){a.search();advance(400);val bar=a.librarySearch!!;assertTrue(a.searchOpen);assertTrue(bar.input.hasFocus());assertTrue(bar.input.isShown);val imm=a.getSystemService(Context.INPUT_METHOD_SERVICE) as android.view.inputmethod.InputMethodManager;assertTrue("search must request IME, not merely display an edit field",Shadows.shadowOf(imm).isSoftInputVisible);assertNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());assertNotNull(descendants(a.root).firstOrNull{it.contentDescription=="Закрыть поиск"});shot("native-search-open").recycle()}
 @Test fun liveSearchKeepsEditorFocusSelectionAndToolbarInstance(){a.search();advance(350);val bar=a.librarySearch!!;val nav=descendants(a.root).filterIsInstance<PolkaNavigation>().single();bar.input.setText("маяка");bar.input.setSelection(3);advance(160);layout();assertEquals("маяка",a.query);assertEquals("Поиск",a.title());assertSame(bar,a.librarySearch);assertSame(nav,descendants(a.root).filterIsInstance<PolkaNavigation>().single());assertTrue(bar.input.hasFocus());assertEquals(3,bar.input.selectionStart);assertEquals(1,a.currentBooks().size);shot("native-search-found").recycle()}
 @Test fun searchMatchesSeriesAndShelfAcrossTabsRatherThanCurrentShelfOnly(){a.books=listOf(JSONObject().put("id","one").put("title","Одна книга").put("series","Северный цикл").put("shelf","Море").put("addedAt",10),JSONObject().put("id","two").put("title","Другая книга").put("shelf","Море").put("addedAt",20));MainActivity::class.java.getDeclaredField("tab").apply{isAccessible=true}.set(a,"quotes");MainActivity::class.java.getDeclaredField("shelf").apply{isAccessible=true}.set(a,"Иная полка");a.query="северный";assertEquals(listOf("one"),a.currentBooks().map{it.str("id")});a.query="море";assertEquals(listOf("two","one"),a.currentBooks().map{it.str("id")})}
 @Test fun clearingSearchKeepsOpenFieldAndClosingRestoresOriginalTab(){MainActivity::class.java.getDeclaredField("tab").apply{isAccessible=true}.set(a,"shelves");a.search();advance(350);val bar=a.librarySearch!!;bar.input.setText("маяк");advance(160);descendants(a.root).first{it.contentDescription=="Очистить поиск"}.performClick();advance(160);assertEquals("",a.query);assertTrue(a.searchOpen);assertTrue(bar.input.hasFocus());assertEquals("Полки",a.title());bar.close();advance(160);assertFalse(a.searchOpen);assertEquals("Полки",a.title());assertEquals("",a.query);assertNotNull(descendants(a.root).firstOrNull{it.contentDescription=="Поиск"})}
 @Test fun searchNoResultsExplainsAllSearchFieldsWithoutSubmitDialog(){a.search();advance(350);a.librarySearch!!.input.setText("несуществующий запрос");advance(160);assertTrue(descendants(a.page).filterIsInstance<TextView>().any{it.text.contains("Поиск идёт по названию, автору, серии и полке.")});shot("native-search-empty").recycle()}
 @Test fun keyboardInsetDoesNotRecreateOrDefocusSearch(){a.search();advance(350);val editor=a.librarySearch!!.input;a.root.dispatchApplyWindowInsets(WindowInsets.Builder().setInsets(WindowInsets.Type.ime(),Insets.of(0,0,0,a.d(300))).build());layout();assertSame(editor,a.librarySearch!!.input);assertTrue(editor.hasFocus());assertEquals(0,a.root.paddingBottom);editor.setText("маяка");advance(160);shot("native-search-ime-inset").recycle()}

 @Test @Config(sdk=[28]) fun launcherUsesAdaptiveIconOnOlderSamsungAndroid(){val info=a.packageManager.getApplicationInfo(a.packageName,0);assertEquals("Polka",a.packageManager.getApplicationLabel(info).toString());val icon=a.getDrawable(info.icon);assertTrue(icon is android.graphics.drawable.AdaptiveIconDrawable);val b=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);icon!!.setBounds(0,0,512,512);icon.draw(Canvas(b));assertEquals("launcher mask must cut corners instead of a painted square",0,Color.alpha(b.getPixel(0,0)));assertNotEquals(0,Color.alpha(b.getPixel(256,256)));val dir=File(System.getProperty("qaOutputDir"),"swipe-0.6.6").apply{mkdirs()};File(dir,"native-icon-api28.png").outputStream().use{b.compress(Bitmap.CompressFormat.PNG,100,it)};b.recycle()}
 @Test fun launcherSupportsThemedIconAndOpticallyCentredSafeGlyph(){val info=a.packageManager.getApplicationInfo(a.packageName,0);assertEquals("Polka",a.packageManager.getApplicationLabel(info).toString());val icon=a.getDrawable(info.icon) as android.graphics.drawable.AdaptiveIconDrawable;assertNotNull(icon.monochrome);val foreground=a.getDrawable(app.polka.nativeapp.R.drawable.ic_launcher_foreground)!!;val b=Bitmap.createBitmap(108,108,Bitmap.Config.ARGB_8888);foreground.setBounds(0,0,108,108);foreground.draw(Canvas(b));var left=108;var right=0;var top=108;var bottom=0;for(y in 0 until 108)for(x in 0 until 108)if(Color.alpha(b.getPixel(x,y))>32){left=minOf(left,x);right=maxOf(right,x);top=minOf(top,y);bottom=maxOf(bottom,y);assertTrue("all symbol pixels must stay within 66dp safe circle",kotlin.math.hypot(x-53.5,y-53.5)<33.5)};assertEquals(53.5,(left+right)/2.0,1.0);assertEquals(53.5,(top+bottom)/2.0,1.0);b.recycle()}

}
